import { BaseClient } from './base.js';
export class GeneralAPI extends BaseClient {
    async getStats() {
        return this.request('/stats', {
            method: 'GET',
        });
    }
    async health() {
        const response = await fetch(this.baseURL);
        if (response.ok) {
            return response.json();
        }
        else {
            throw new Error('API is down');
        }
    }
}
